from decimal import Decimal

def parse_number(text: str) -> Decimal:
    # only stdlib, never float
    if not isinstance(text, str):
        raise ValueError("invalid input")
    # 1. strip leading/trailing whitespace (space, tab, NBSP + other whitespace)
    s = text.strip(" \t\n\r\f\v\u00a0")
    if s == "":
        raise ValueError("empty input")
    is_negative = False
    has_open = "(" in s
    has_close = ")" in s
    # 2. parentheses handling
    if has_open or has_close:
        if s.startswith("(") and s.endswith(")"):
            inner = s[1:-1]
            # sign inside or outside combined with parentheses is invalid
            # outside sign impossible here since starts with '(' but check anyway
            # any sign inside is invalid
            if "+" in inner or "-" in inner:
                raise ValueError("sign with parentheses")
            if "(" in inner or ")" in inner:
                raise ValueError("unbalanced parentheses")
            is_negative = True
            s = inner
        else:
            raise ValueError("unbalanced parentheses")
    else:
        # 3. optional leading sign when no parentheses
        if s.startswith("+") or s.startswith("-"):
            is_negative = (s[0] == "-")
            s = s[1:]
            if s == "":
                raise ValueError("sign alone")
            if "+" in s or "-" in s:
                raise ValueError("bad sign placement")
            if "(" in s or ")" in s:
                raise ValueError("bad parentheses")
        else:
            if "+" in s or "-" in s:
                raise ValueError("bad sign placement")
    # 4. interior spaces (space and NBSP) are thousands separators: remove them
    t = s.replace(" ", "").replace("\u00a0", "")
    if t == "":
        raise ValueError("empty number")
    allowed = set("0123456789.,")
    for ch in t:
        if ch not in allowed:
            raise ValueError("invalid character")
    has_digit = False
    for ch in t:
        if "0" <= ch <= "9":
            has_digit = True
            break
    if not has_digit:
        raise ValueError("no digits")

    def check_digits(part: str) -> bool:
        if part == "":
            return False
        for c in part:
            if not ("0" <= c <= "9"):
                return False
        return True

    def validate_thousands(int_part: str, thou: str) -> str:
        groups = int_part.split(thou)
        for g in groups:
            if g == "":
                raise ValueError("bad grouping")
        if not (1 <= len(groups[0]) <= 3):
            raise ValueError("bad grouping")
        for g in groups[1:]:
            if len(g) != 3:
                raise ValueError("bad grouping")
        for g in groups:
            if not check_digits(g):
                raise ValueError("bad grouping")
        return "".join(groups)

    has_dot = "." in t
    has_comma = "," in t
    normalized = None
    # 5-6. separator decision and grouping validation
    if has_dot and has_comma:
        last_dot = t.rfind(".")
        last_comma = t.rfind(",")
        if last_comma > last_dot:
            dec = ","
            thou = "."
        else:
            dec = "."
            thou = ","
        if t.count(dec) != 1:
            raise ValueError("multiple decimal separators")
        int_part, frac_part = t.split(dec)
        if int_part == "" or frac_part == "":
            raise ValueError("empty integer or decimal part")
        if not check_digits(frac_part):
            raise ValueError("bad decimal part")
        for c in int_part:
            if c not in "0123456789" + thou:
                raise ValueError("bad integer part")
        if thou in int_part:
            int_digits = validate_thousands(int_part, thou)
        else:
            if not check_digits(int_part):
                raise ValueError("bad integer part")
            int_digits = int_part
        normalized = int_digits + "." + frac_part
    elif has_comma:
        if t.count(",") > 1:
            int_digits = validate_thousands(t, ",")
            normalized = int_digits
        else:
            int_part, frac_part = t.split(",")
            if int_part == "" or frac_part == "":
                raise ValueError("empty integer or decimal part")
            if not check_digits(int_part) or not check_digits(frac_part):
                raise ValueError("bad decimal number")
            normalized = int_part + "." + frac_part
    elif has_dot:
        if t.count(".") > 1:
            int_digits = validate_thousands(t, ".")
            normalized = int_digits
        else:
            int_part, frac_part = t.split(".")
            if int_part == "" or frac_part == "":
                raise ValueError("empty integer or decimal part")
            if not check_digits(int_part) or not check_digits(frac_part):
                raise ValueError("bad decimal number")
            normalized = int_part + "." + frac_part
    else:
        if not check_digits(t):
            raise ValueError("bad integer")
        normalized = t
    sign = "-" if is_negative else ""
    try:
        return Decimal(sign + normalized)
    except Exception:
        raise ValueError("invalid decimal")
